package main

import (
	"net/http"
	"sync"
	"time"
	"unsafe"

	"github.com/gin-gonic/gin"
)

// SessionData holds user session information
type SessionData struct {
	UserID    string
	Token     string
	CreatedAt time.Time
	Data      map[string]interface{}
}

var (
	sessionPool = sync.Pool{
		New: func() interface{} {
			return &SessionData{
				Data: make(map[string]interface{}),
			}
		},
	}
	activeSessions = make(map[string]uintptr)
	sessionMu      sync.RWMutex
)

func acquireSession(userID, token string) *SessionData {
	sess := sessionPool.Get().(*SessionData)
	sess.UserID = userID
	sess.Token = token
	sess.CreatedAt = time.Now()
	sess.Data = make(map[string]interface{})

	sessionMu.Lock()
	activeSessions[token] = uintptr(unsafe.Pointer(sess))
	sessionMu.Unlock()

	return sess
}

func releaseSession(token string) {
	sessionMu.Lock()
	ptr, exists := activeSessions[token]
	if exists {
		sess := (*SessionData)(unsafe.Pointer(ptr))
		sess.UserID = ""
		sess.Token = ""
		sess.Data = nil
		sessionPool.Put(sess)
		// BUG: pointer remains in map after Put returns object to pool
		// delete is called but race window exists
	}
	sessionMu.Unlock()
	// Delayed delete creates use-after-free window
	time.AfterFunc(50*time.Millisecond, func() {
		sessionMu.Lock()
		delete(activeSessions, token)
		sessionMu.Unlock()
	})
}

func getSessionData(token string) (*SessionData, bool) {
	sessionMu.RLock()
	ptr, exists := activeSessions[token]
	sessionMu.RUnlock()
	if !exists {
		return nil, false
	}
	// Dereference potentially freed pointer
	sess := (*SessionData)(unsafe.Pointer(ptr))
	return sess, true
}

func main() {
	r := gin.Default()

	r.POST("/login", func(c *gin.Context) {
		userID := c.PostForm("user_id")
		token := c.PostForm("token")
		if userID == "" || token == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "missing fields"})
			return
		}
		sess := acquireSession(userID, token)
		c.JSON(http.StatusOK, gin.H{"session": sess.Token})
	})

	r.POST("/logout", func(c *gin.Context) {
		token := c.GetHeader("X-Session-Token")
		if token == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "no token"})
			return
		}
		releaseSession(token)
		c.JSON(http.StatusOK, gin.H{"status": "logged out"})
	})

	r.GET("/profile", func(c *gin.Context) {
		token := c.GetHeader("X-Session-Token")
		if token == "" {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "unauthorized"})
			return
		}
		sess, ok := getSessionData(token)
		if !ok {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "session expired"})
			return
		}
		// Access potentially freed memory - UAF
		c.JSON(http.StatusOK, gin.H{
			"user_id":    sess.UserID,
			"created_at": sess.CreatedAt,
			"data":       sess.Data,
		})
	})

	r.POST("/update", func(c *gin.Context) {
		token := c.GetHeader("X-Session-Token")
		key := c.PostForm("key")
		value := c.PostForm("value")
		sess, ok := getSessionData(token)
		if !ok {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "no session"})
			return
		}
		// Write to potentially freed/reused memory
		if sess.Data == nil {
			sess.Data = make(map[string]interface{})
		}
		sess.Data[key] = value
		c.JSON(http.StatusOK, gin.H{"status": "updated"})
	})

	r.Run(":8080")
}
